"""Bilingual, source-backed worked examples. Never include real RF/card credentials."""
from html import escape

UPSTREAM = 'https://github.com/DarkFlippers/unleashed-firmware/blob/4c55ea75d09b37e646d24486addeadb7e076319f/'

def render(zh, diagram):
    def t(en,cn): return cn if zh else en
    def p(en,cn): return '<p>'+t(en,cn)+'</p>'
    def heading(id,en,cn): return f'<h3 id="{id}">'+t(en,cn)+'</h3>'
    def steps(items): return '<ol class="steps">'+''.join('<li>'+t(*item)+'</li>' for item in items)+'</ol>'
    def note(en,cn): return '<aside class="note">'+t(en,cn)+'</aside>'
    def refs(items): return '<div class="refs">'+t('Sources','原始资料')+' · '+' · '.join(f'<a href="{url}" target="_blank" rel="noopener noreferrer">{escape(t(en,cn))}</a>' for url,en,cn in items)+'</div>'
    nice = heading('nice-unleashed','Worked example: install Unleashed','操作实例：升级至 Unleashed') + note(
        'The site owner reports having verified the Unleashed → capture → Nice emulation method on their own equipment. This write-up combines that experience with upstream documentation; it is not a new hardware test by this site update. The exact tested firmware tag and receiver configuration were not supplied, so no universal compatibility is implied.',
        '站主已验证其自有设备上的 Unleashed → 捕获 → Nice 模拟方法。此处将该经验与上游资料整理为操作实例；本次网站更新未重新连接硬件实测。原验证未提供准确固件标签及接收器配置，因此不推定所有型号通用。') + p(
        'Scope: an owned Nice FLO2R-S / FLOR-S remote and its receiver. Check the decoded protocol, not just the case label. FLO fixed code and Nice O-Code are separate variants. Keep a working original remote and access to the receiver’s administration / resynchronization procedure.',
        '适用对象：自有 Nice FLO2R-S / FLOR-S 遥控器及其接收器。以解码协议而非外壳判断；FLO 固定码、Nice O-Code 是不同变体。保留可用的原遥控器，并确保能够管理接收器及执行重同步。') + steps([
        ('Back up the microSD card, saved remotes and settings with qFlipper / a card reader. Record the current firmware. Insert a working microSD card, charge the device and use a USB data cable. Do not publish backups.', '用 qFlipper / 读卡器备份 microSD、已存遥控器及配置，记录原固件。插入可用 microSD、保证电量并使用 USB 数据线；备份不要公开。'),
        ('Open the official Unleashed project’s Releases link below. Use a tagged Release, not an unreviewed third-party bundle. Download its matching f7 update .tgz if choosing the file-install route; do not unpack that archive for qFlipper.', '从下方 Unleashed 项目的 Releases 获取带标签的 Release，而不是来源不明的整合包。若采用文件安装，下载对应 f7 更新 .tgz；供 qFlipper 使用时不要解压。'),
        ('Browser route: open web.unleashedflip.com in a Chromium browser, connect the device, click Connect, select the Flipper in the browser prompt, select Release and click Install. Wait through firmware and SD-resource installation and reboot; do not disconnect midway.', '浏览器方式：用 Chromium 系浏览器打开 web.unleashedflip.com，接好设备，点击 Connect，在浏览器弹窗选择 Flipper，选择 Release 后 Install。等待固件、SD 资源安装及重启，不要中途断开。'),
        ('Alternative: qFlipper → Install from file → select the downloaded .tgz → wait for completion. The current upstream guide recommends qUnleashed, which also installs firmware and resources; the browser and qFlipper paths remain documented alternatives.', '替代方式：qFlipper → Install from file → 选择下载的 .tgz → 等待完成。当前上游指南推荐 qUnleashed，可一并安装固件与资源；浏览器及 qFlipper 仍是文档列出的方式。'),
        ('After reboot, check Settings → About for the installed version and open Sub-GHz. If assets are missing, complete installation with the matching release resources. To return to stock, use qFlipper’s official Release update; if the device cannot boot, use official DFU recovery / Repair.', '重启后在 Settings → About 核对版本，打开 Sub-GHz。若缺少资源，使用同一版本配套资源完成安装。回到官方固件可用 qFlipper 的官方 Release 更新；无法启动时按官方 DFU 恢复 / Repair 流程处理。')]) + refs([
        ('https://github.com/DarkFlippers/unleashed-firmware/releases','Unleashed releases','Unleashed 发布包'),
        (UPSTREAM+'documentation/HowToInstall.md','Pinned installation guide','固定版本安装指南'),
        ('https://web.unleashedflip.com','Project web installer','项目 Web 安装器'),
        ('https://docs.flipper.net/zero/basics/firmware-update/firmware-recovery','Official recovery','官方恢复指南')])
    nice += heading('nice-capture-emulate','Capture, inspect and emulate a Nice FLOR-S remote','捕获、观察并模拟 Nice FLOR-S 遥控器') + diagram('nice-worked',('Nice: from capture to a stateful transmission','Nice：从捕获到有状态发送'),('A decoded capture feeds an encoder, not a RAW loop. Receiver acceptance is a separate check.','解码捕获交给编码器，而不是循环播放 RAW；接收端是否接受需独立验证。')) + steps([
        ('On your test bench, disconnect the gate / door actuator and monitor the receiver LED or relay. Open Sub-GHz → Read → Config, select the confirmed frequency (433.92 MHz for this FLOR-S example) and the matching AM/OOK preset. Start with the firmware’s suitable AM preset; “650” is a receiver-bandwidth setting, not the remote’s carrier frequency.', '实验台先断开门机等执行机构，观察接收板 LED / 继电器。进入 Sub-GHz → Read → Config，选择已确认频率（本 FLOR-S 示例为 433.92 MHz）及匹配的 AM/OOK preset。使用适合的 AM 预设；“650”是接收带宽设置，不是遥控器载频。'),
        ('Return to Read and press your remote once nearby. Open the decoded entry: confirm Nice FloR-S and its displayed bit length (commonly 52 for this variant). Record Serial, Button and Counter locally. The bit length is not a cryptographic security level.', '返回 Read，在近处按一下自有遥控器，打开解码条目：确认 Nice FloR-S 与显示位长（此变体通常为 52）。在本地记录 Serial、Button、Counter；位长不等于密码安全强度。'),
        ('Compare a small number of separate presses on the same button: the identity/button should be consistent while the counter follows the protocol. Repeated frames within one burst are not separate presses. Save the decoded entry under a private lab name. This is passive reception of your own remote, not interception of traffic between unknown parties.', '少量比较同一按键的独立按压：身份 / 按键应一致，计数器按协议变化。同一发射突发里的重复帧不算多次按压。将解码条目 Save 为私有实验名称；这里的“嗅探”是被动接收自有遥控器，而非截取不明对象的通信。'),
        ('Open Sub-GHz → Saved → your saved entry → Emulate. In the transmitter screen use Send / the indicated OK control once, then check the receiver indicator. Supported Unleashed firmware loads the decoded identity/state and generates a transmission using its Nice encoder; do not substitute Read RAW playback for this step.', '进入 Sub-GHz → Saved → 已保存条目 → Emulate，在发射界面用 Send / 所示 OK 控件单次发送，再检查接收器指示。支持该协议的 Unleashed 使用已解码身份 / 状态交给 Nice 编码器生成发射；此处不能用 Read RAW 重放代替。'),
        ('Record the firmware, receiver model, preset and counter mode, and whether the receiver accepted the transmission. Then make a small controlled comparison with the original remote. A successful result is receiver acceptance, not simply “TX completed”. Keep the current working .sub private and do not repeatedly overwrite it with an older counter-state backup.', '记录固件、接收器型号、preset、counter mode 及接收结果，再与原遥控器做少量受控对照。成功标准是接收端接受，而不只是“发射完成”。将当前工作 .sub 保持私有，不要反复用旧计数器备份覆盖它。'),
        ('If reception fails or the original remote stops working, stop sending. Recheck protocol, resources, pairing and receiver-specific synchronization. Restoring an old .sub file does not roll back receiver state. Use the manufacturer’s authorized resynchronization / enrollment instructions rather than trying many counter jumps.', '接收失败或原遥控器异常时停止发送，检查协议、资源、配对及接收器的同步规则。恢复旧 .sub 不会回退接收端状态；按厂商授权流程重同步 / 注册，而不是盲试大量计数器跳变。')]) + p(
        '<strong>CounterMode is receiver-specific.</strong> Upstream documents mode 0 as regular rolling behavior using the global increment (normally +1), mode 1 for FLOXI2R, and mode 2 for OX2. These are not interchangeable “try until it opens” presets. The owner’s report does not identify a special mode; do not assume modes 1/2 apply to every Nice receiver. Advanced configuration is described in the linked guide; inspect your private saved file and record the actual setting.',
        '<strong>CounterMode 与接收器有关。</strong>上游把 mode 0 定义为使用全局增量（通常 +1）的常规滚动方式，mode 1 对应 FLOXI2R，mode 2 对应 OX2；它们不是可以随意轮试的“开门模式”。站主的验证未指明特殊 mode，不应推断所有 Nice 接收器都用 1/2。高级配置见下方指南，检查私有保存文件并记录实际设置。') + note(
        'A rolling-code capture is not a promise of a portable clone. Firmware decoder/encoder support, matching SD assets, receiver enrollment and synchronization all matter. Radio transmission must also comply with local frequency and power rules. Never put the real .sub file, serial, key material or counter history in the public site.',
        '捕获到滚动码不等于获得通用克隆。固件解码 / 编码支持、配套 SD 资源、接收器注册与同步均影响结果；发射仍需符合当地频率及功率规定。真实 .sub、序列号、密钥材料与计数器历史不要放进公开网站。') + refs([
        (UPSTREAM+'lib/subghz/protocols/nice_flor_s.c','Nice decoder / encoder implementation','Nice 解码 / 编码实现'),
        (UPSTREAM+'applications/main/subghz/scenes/subghz_scene_saved_menu.c','Saved → Emulate implementation','Saved → Emulate 菜单实现'),
        (UPSTREAM+'documentation/SubGHzCounterMode.md','Receiver-specific counter modes','接收器相关计数器模式'),
        ('https://docs.flipper.net/zero/sub-ghz/read','Official Read workflow','官方 Read 操作'),
        ('https://www.niceforyou.com/sites/default/files/upload/manuals/ISTFLORM.4852.pdf','Nice FLOR receiver manual','Nice FLOR 接收器手册')])

    nfc = heading('m1-emulate','Worked example: read and emulate a Classic 1K test card','操作实例：读取并模拟 Classic 1K 测试卡') + p(
        'Use an owned / authorized MIFARE Classic 1K card with known usable keys and a lab reader. Official firmware is sufficient for the supported read/emulate/Magic-card paths; Unleashed is not required. This is a reproducible procedure, not a claim that a particular access-control system was tested.',
        '准备自有 / 授权的 MIFARE Classic 1K 卡、可用的已知密钥及实验读头。受支持的读取 / 模拟 / Magic 写卡流程可用官方固件完成，不要求 Unleashed。以下是可复现步骤，不代表已实测某套门禁系统。') + diagram('m1-worked',('One card image, two different experiments','一份卡片镜像，两种不同实验'),('Flipper emulation and a physical copy require independent verification. A UID match alone is insufficient.','Flipper 模拟与实体复制必须分别验证；仅 UID 相同不足以证明成功。')) + steps([
        ('Open NFC → Read. Hold the card against the back of Flipper, steady over the NFC antenna. Confirm that the result is MIFARE Classic 1K at 13.56 MHz, not a 125 kHz LF badge, DESFire or another NFC family.', '打开 NFC → Read，将卡贴在 Flipper 背面 NFC 天线区域并保持稳定，确认结果为 13.56 MHz 的 MIFARE Classic 1K，而不是 125 kHz 低频卡、DESFire 或其他 NFC 家族。'),
        ('Let reading finish. Check UID/type and sector coverage: a Classic 1K has 16 sectors. The interface can show up to 32 key slots (A/B per sector), but key count alone does not prove complete usable data. If required sectors are missing, resolve that before copying; add known lab keys through NFC → Extra Actions → MIFARE Classic Keys as appropriate.', '等待读取完成，检查 UID / 类型及扇区覆盖：Classic 1K 有 16 扇区。界面最多可显示 32 个密钥槽（每扇区 A/B），但密钥数量本身不证明所需数据完整。缺少必要扇区时先补齐；可按需通过 NFC → Extra Actions → MIFARE Classic Keys 添加已知实验密钥。'),
        ('Choose More → Save and name it lab-m1-original. Keep a private backup of the original .nfc and record the read coverage. Treat it as a credential, not a shareable sample.', '选择 More → Save，命名 lab-m1-original。私有备份原始 .nfc，并记录读取覆盖率；把它当作凭据，而不是可公开的示例文件。'),
        ('Open NFC → Saved → lab-m1-original → Emulate. Hold the back of Flipper at the lab reader’s antenna and keep it steady. Compare the reader’s result with the original card; use reader logs when available to distinguish UID-only acceptance from sector authentication and application-data checks.', '进入 NFC → Saved → lab-m1-original → Emulate，将 Flipper 背面贴近实验读头天线并保持稳定。将结果与原卡比较，有日志时区分仅读 UID、扇区认证及应用数据检查。'),
        ('Stop emulation and inspect any changed state before the next experiment. Reader writes during emulation may be stored in a .shd shadow file; the original .nfc and the current emulated state are not necessarily identical. Do not blindly delete or restore this state when the system maintains counters or balances.', '退出模拟，下一项实验前检查状态变化。读头在模拟中写入的数据可能进入 .shd 影子文件；原始 .nfc 不一定等于当前模拟状态。系统维护计数器或余额时，不要盲目删除或恢复该状态。')])
    nfc += heading('m1-copy','Worked example: write a compatible Magic blank','操作实例：写入兼容 Magic 空白卡') + steps([
        ('Choose a compatible MIFARE Classic Magic blank with the right capacity and supported generation. The official NFC Magic guide distinguishes Gen1 (1K), compatible Gen2 (1K/4K), and Gen4. A normal Classic card generally cannot rewrite its manufacturer UID, and T5577 LF media are not a substitute.', '准备容量匹配、代际受支持的 MIFARE Classic Magic 空白卡。官方 NFC Magic 文档区分 Gen1（1K）、兼容 Gen2（1K / 4K）及 Gen4。普通 Classic 卡的厂商 UID 通常不可改写，T5577 低频卡也不能替代。'),
        ('Remove the original card from the work area. Open Apps → NFC → NFC Magic → Check Magic Tag and place only the blank at the antenna. Confirm the detected generation/type. For a password-protected Gen4 blank, use its known configured password; do not assume it is the default.', '将原卡移出操作区域。打开 Apps → NFC → NFC Magic → Check Magic Tag，仅将空白卡贴近天线，确认检测到的代际 / 类型。若 Gen4 已设置密码，使用其已知配置密码，不要假定仍是默认值。'),
        ('Choose More → Write, select the saved complete test-card image, and hold the blank still until writing finishes. Choose the intended baseline / updated state consciously; a previous emulation session may have changed the shadow state.', '选择 More → Write，选取已保存且完整的测试卡镜像，保持空白卡位置直到写入完成。明确选择原始基线还是更新后的状态；此前模拟可能已改变影子状态。'),
        ('Read the newly written card again through NFC → Read and save it separately as lab-m1-copy-check. Compare UID, card type/capacity, required-sector coverage, access conditions and application data. Key fields may be masked or represented differently under access permissions; do not equate visible trailer bytes with all secret keys.', '重新用 NFC → Read 读取新卡，另存为 lab-m1-copy-check。比较 UID、卡类型 / 容量、必要扇区覆盖、访问条件及应用数据。密钥字段可能因访问权限被掩码或以不同方式表示，不能把可见尾块字节等同于全部秘密密钥。'),
        ('Test the original card, Flipper emulation and physical copy separately on the authorized reader. Record success/failure and authentication behavior. Anti-passback rules, server-side state, reader timing or clone detection can reject a copy even when the UID and readable bytes match.', '在授权读头上分别测试原卡、Flipper 模拟及实体副本，记录成功 / 失败及认证行为。即使 UID 和可读字节一致，防潜回、服务端状态、时序或克隆检测仍可能拒绝副本。')]) + note(
        '<strong>Write to Initial Card is different.</strong> It synchronizes changes back to the original compatible card; it is not the generic “copy to a new blank” command. UID-only detection is not a full Classic dump, and these examples do not imply DESFire / CPU cards can be cloned by reading their UID.',
        '<strong>Write to Initial Card 不是上述复制命令。</strong>它用于将变化同步回原始兼容卡，并非通用的“写入新空白卡”。仅读 UID 不等于完整 Classic dump；本实例也不表示 DESFire / CPU 卡能靠读取 UID 完成克隆。') + refs([
        ('https://docs.flipper.net/zero/nfc/read','Official reading, emulation and shadow files','官方读取、模拟与影子文件'),
        ('https://docs.flipper.net/zero/nfc/magic-cards','Official NFC Magic compatibility and writing','官方 NFC Magic 兼容性与写卡'),
        ('https://www.nxp.com/docs/en/data-sheet/MF1S50YYX_V1.pdf','NXP Classic 1K datasheet','NXP Classic 1K 数据手册')])
    return nice, nfc
